export interface TextSegment {
  text: string;
  /** Kana reading for this segment. Only present for segments containing kanji. */
  reading?: string;
}

/**
 * Renders structured segments with <ruby>. Readings come from the data (never generated by character
 * substitution); furigana can be hidden without affecting any translation display.
 */
export function Furigana({ segments, showReading = true }: { segments: TextSegment[]; showReading?: boolean }) {
  return (
    <span lang="ja">
      {segments.map((s, i) =>
        s.reading && showReading ? (
          <ruby key={i}>
            {s.text}
            <rp>(</rp>
            <rt>{s.reading}</rt>
            <rp>)</rp>
          </ruby>
        ) : (
          <span key={i}>{s.text}</span>
        ),
      )}
    </span>
  );
}
